                    try { window.__AutoBILog5?.note('Gi\u1EDD c\u00F4ng: API doanh thu nh\u00E2n vi\u00EAn l\u1ED7i \u2014 ' + (apiError && apiError.message)); } catch (_) { }
                    revenue = null;
