        const ratio = r => { const pct = average ? r.hours / average * 100 : 0; return '<div class="ratio"><span class="track"><i style="width:' + Math.min(100, pct) + '%;background:' + (pct < 70 ? '#ff9c16' : pct < 100 ? '#438dff' : '#39c975') + '"></i></span><b>' + number(pct, 0) + '%</b></div>'; };
        let html = '<header><span class="clock">\u25F7</span><div class="heading"><small>AUTOBI \u00B7 GI\u1EDC C\u00D4NG</small><h1>Gi\u1EDD c\u00F4ng & <em>N\u0103ng su\u1EA5t</em></h1><p>' + (result ? displayDate(result.range.from) + ' \u2013 ' + displayDate(result.range.to) + ' \u00B7 C\u1EADp nh\u1EADt ' + new Date(result.at).toLocaleString('vi-VN') : 'Ch\u01B0a c\u00F3 b\u00E1o c\u00E1o Gi\u1EDD c\u00F4ng') + '</p></div><div class="motto">L\u00E0m \u0111\u00FAng gi\u1EDD<br>Hi\u1EC7u qu\u1EA3 h\u01A1n! <span>\u2582\u2585\u2587 \u2197</span></div><button id="wt-close">\u23FB \u0110\u00F3ng</button></header>';
        html += '<div class="content">';
        if (status?.message)
            html += '<div class="notice" role="status">' + esc(status.message) + '</div>';
        if (!result)
            return html + '<p class="empty">Ch\u1ECDn B\u00E1o c\u00E1o Gi\u1EDD c\u00F4ng \u0111\u1EC3 ch\u1EA1y ri\u00EAng, ho\u1EB7c B\u00E1o c\u00E1o ALL & L\u01B0u Data \u0111\u1EC3 ch\u1EA1y li\u1EC1n m\u1EA1ch.</p></div>';
        if (result.partial)
            html += '<div class="notice">D\u1EEF li\u1EC7u c\u0169 m\u1EDBi c\u00F3 ' + result.rows + '/' + result.total + ' d\u00F2ng. H\u00E3y ch\u1EA1y l\u1EA1i \u0111\u1EC3 l\u1EA5y \u0111\u1EE7.</div>';
        const stat = (icon, label, value, unit, kind) => '<div class="stat ' + kind + '"><span class="stat-icon">' + icon + '</span><div><small>' + label + '</small><strong>' + value + '</strong><span class="unit">' + unit + '</span></div></div>';
        html += '<div class="stats">' + stat('\u25A6', 'T\u1ED5ng s\u1ED1 si\u00EAu th\u1ECB', shops.size, 'si\u00EAu th\u1ECB', 'blue') + stat('\u265F', 'T\u1ED5ng nh\u00E2n vi\u00EAn', unique, 'nh\u00E2n vi\u00EAn', 'pink') + stat('\u25F7', 'T\u1ED5ng gi\u1EDD c\u00F4ng', number(total), 'gi\u1EDD', 'green') + stat('\u25A5', 'Trung b\u00ECnh/nh\u00E2n vi\u00EAn', number(average), 'gi\u1EDD', 'orange') + '</div>';
        html += '<div class="toolbar"><button id="wt-open-all" class="primary">\u25A6 M\u1EDF t\u1EA5t c\u1EA3</button><button id="wt-close-all">\u2637 Thu g\u1ECDn t\u1EA5t c\u1EA3</button><span class="period">\u25A6 ' + displayDate(result.range.from) + ' \u2013 ' + displayDate(result.range.to) + '</span><select id="wt-shop" aria-label="L\u1ECDc si\u00EAu th\u1ECB">' + select('all', 'T\u1EA5t c\u1EA3 si\u00EAu th\u1ECB', filters.shop) + allShops.map(([id, name]) => select(id, name, filters.shop)).join('') + '</select><select id="wt-role" aria-label="L\u1ECDc ch\u1EE9c v\u1EE5">' + select('all', 'T\u1EA5t c\u1EA3 ch\u1EE9c v\u1EE5', filters.role) + select('sales', 'Nh\u00E2n vi\u00EAn b\u00E1n h\u00E0ng', filters.role) + select('management', 'Tr\u01B0\u1EDFng ca & Qu\u1EA3n l\u00FD', filters.role) + '</select><select id="wt-metric" aria-label="Lo\u1EA1i doanh thu">' + select('converted', 'DT quy \u0111\u1ED5i', filters.metric) + select('actual', 'DT th\u1EF1c', filters.metric) + '</select></div>';
        html += '<p class="hint">' + result.rows + ' d\u00F2ng ngu\u1ED3n \u00B7 ' + (result.convertedMatched ?? staff.filter(r => r.convertedRevenue != null).length) + ' d\u00F2ng NV c\u00F3 DT quy \u0111\u1ED5i. T\u1EF7 l\u1EC7 so v\u1EDBi TB = gi\u1EDD t\u1EA1i shop / trung b\u00ECnh c\u1EE7a nh\u00E2n vi\u00EAn trong ph\u1EA1m vi \u0111ang xem. Doanh thu: ' + esc(result.unit || 'Tri\u1EC7u \u0111\u1ED3ng') + '.</p>';
        let index = 0;
