/* V80: Diagnostics — ghi lỗi chưa bắt được (tối đa 50), xuất log từ menu Tampermonkey */
(function () {
    'use strict';
    if (window.top !== window.self || window.__AutoBIDiag80)
        return;
    const KEY = 'autobi_diag80', MAX = 50;
    const read = () => { try {
        const v = GM_getValue(KEY, '[]');
        const a = JSON.parse(v);
        return Array.isArray(a) ? a : [];
    }
    catch (_) {
        return [];
    } };
    const push = (type, err) => {
        try {
            const msg = String((err && (err.stack || err.message)) || err || '').slice(0, 600);
            if (/ResizeObserver loop/i.test(msg))
                return;
            const a = read();
            a.push({ t: new Date().toISOString(), type, url: location.pathname, msg });
            GM_setValue(KEY, JSON.stringify(a.slice(-MAX)));
        }
        catch (_) { }
    };
    window.addEventListener('error', e => push('error', e.error || e.message));
    window.addEventListener('unhandledrejection', e => push('promise', e.reason));
    const exportLog = () => {
        const a = read();
        const text = 'AutoBI ' + (typeof GM_info !== 'undefined' ? GM_info.script.version : '') + '\n' + (a.length ? a.map(x => x.t + ' [' + x.type + '] ' + x.url + '\n' + x.msg).join('\n\n') : 'Kh\u00F4ng c\u00F3 l\u1ED7i n\u00E0o \u0111\u01B0\u1EE3c ghi.');
        const url = URL.createObjectURL(new Blob([text], { type: 'text/plain;charset=utf-8' }));
        const el = document.createElement('a');
        el.href = url;
        el.download = 'autobi-log-' + Date.now() + '.txt';
        document.body.appendChild(el);
        el.click();
        el.remove();
        setTimeout(() => URL.revokeObjectURL(url), 5000);
    };
    window.__AutoBIDiag80 = { read, export: exportLog, clear: () => GM_setValue(KEY, '[]') };
    try {
        if (typeof GM_registerMenuCommand === 'function') {
            GM_registerMenuCommand('AutoBI: Xu\u1EA5t log l\u1ED7i', exportLog);
            GM_registerMenuCommand('AutoBI: X\u00F3a log l\u1ED7i', () => window.__AutoBIDiag80.clear());
        }
    }
    catch (_) { }
})();

